<script setup lang="ts">
// Ambient cycle and flowing-path implementation copied from NJUAnimatedEveNet.vue.
// The graph is fully visible from entry; there are no progressive click states.
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue'
import {animate} from 'animejs'
import {useSlideContext} from '@slidev/client'
const props=defineProps<{kind:string}>(); const {$nav,$page,$renderContext}=useSlideContext()
const ambient=reactive({cycle:0});const reduced=ref(false),hidden=ref(false);let loop:any,media:MediaQueryList
const running=computed(()=>$nav.value.currentPage===$page.value&&$renderContext.value==='slide'&&!reduced.value&&!hidden.value)
function syncLoop(){loop?.cancel();if(running.value)loop=animate(ambient,{cycle:{from:ambient.cycle,to:ambient.cycle+1},duration:2500,ease:'linear',loop:true})}
function visibility(){hidden.value=document.hidden}function preference(){reduced.value=media.matches||location.search.includes('static')}
onMounted(()=>{media=matchMedia('(prefers-reduced-motion: reduce)');media.addEventListener('change',preference);document.addEventListener('visibilitychange',visibility);preference();visibility();syncLoop()});watch(running,syncLoop);onBeforeUnmount(()=>{loop?.cancel();media?.removeEventListener('change',preference);document.removeEventListener('visibilitychange',visibility)})
const colors=['#77c9ff','#f0c36e','#baa5ff','#70dcb2','#f69cab']
const definitions:any={
