workflow:{nodes:[[10,95,150,96,'Generation','Beam / hard process',0],[212,95,150,96,'DSimu','Geant4 simulation',1],[414,95,150,96,'DEvent','Truth + hit records',2],[616,95,235,96,'DAna','Digitisation / reconstruction',3],[622,247,230,67,'Physics analysis','Selections + normalisation',4],[213,247,350,67,'DDis event display','Inspect geometry, truth and response',0]],edges:['M160 143 H212','M362 143 H414','M564 143 H616','M733 191 V247','M489 191 V224 H389 V247']},
filterCompact:{box:'0 0 880 175',nodes:[[15,0,250,70,'Stage 0','Primary track only',0],[315,0,250,70,'Stage 1','Secondaries in the ROI',1],[615,0,250,70,'Stage 2','Release remaining tracks',3],[15,105,250,65,'Reject early','Primary requirement failed',4],[315,105,250,65,'Reject early','Required interaction absent',4],[615,105,250,65,'Write selected event','Particle tracking complete',2]],edges:['M265 35 H315','M565 35 H615','M140 70 V105','M440 70 V105','M740 70 V105']},
filter:{nodes:[[15,70,230,100,'Stage 0','Primary track only',0],[325,70,230,100,'Stage 1','Secondaries in the ROI',1],[635,70,230,100,'Stage 2','Release remaining tracks',3],[15,245,230,68,'Reject early','Primary filter failed',4],[325,245,230,68,'Reject early','Required interaction absent',4],[635,245,230,68,'Write selected event','Complete selected event',2]],edges:['M245 120 H325','M555 120 H635','M130 170 V245','M440 170 V245','M750 170 V245']},
digitCompact:{box:'0 0 880 100',nodes:[[10,10,185,80,'Energy deposit','Geant4 hits',0],[230,10,185,80,'Optical response','Photon tracking / LUT',1],[450,10,185,80,'SiPM + ADC','Recovery / noise / sampling',2],[670,10,200,80,'Calibrated energy','Cell response / clusters',3]],edges:['M195 50 H230','M415 50 H450','M635 50 H670']},
digit:{nodes:[[15,110,158,100,'Energy deposit','Geant4 hits',0],[232,110,158,100,'Optical response','Photon tracking / LUT',1],[449,110,158,100,'SiPM + ADC','Recovery, noise, sampling',2],[666,110,195,100,'Calibrated energy','Cell response + clusters',3]],edges:['M173 160 H232','M390 160 H449','M607 160 H666']},
actsCompact:{box:'0 0 440 340',nodes:[[0,0,200,80,'DSS event + geometry','Strip pairs / magnetic field',0],[240,0,200,80,'ACTS conversion','Surfaces / source links',1],[240,130,200,80,'Truth-smeared seeds','Reference configuration',4],[0,130,200,80,'Combinatorial KF','Track candidates',2],[0,260,200,80,'Tracks + vertices','Parameters / fit quality',3],[240,260,200,80,'ECAL seed interface','Extrapolated impact points',0]],edges:['M200 40 H240','M340 80 V130','M240 170 H200','M100 210 V260','M200 300 H240']},
acts:{nodes:[[10,75,215,95,'DSS event + geometry','Strip pairs / field map',0],[330,75,220,95,'ACTS conversion','Surfaces / source links',1],[650,75,220,95,'Truth-smeared seeds','Reference configuration',4],[650,240,220,80,'Combinatorial KF','Track candidates',2],[330,240,220,80,'Tracks + vertices','Parameters / fit quality',3],[10,240,215,80,'ECAL seed interface','Extrapolated impact points',0]],edges:['M225 122 H330','M550 122 H650','M760 170 V240','M650 280 H550','M330 280 H225']},
tracking:{nodes:[[15,110,165,100,'Strip measurements','Stereo coordinate pairs',0],[238,110,165,100,'Track finding','Candidate hit association',1],[461,110,165,100,'Track fitting','Field + material + errors',2],[684,110,180,100,'Physics observables','Momentum / multiplicity',3]],edges:['M180 160 H238','M403 160 H461','M626 160 H684']},
model:{nodes:[[315,115,250,95,'DEvent','Shared ROOT event record',1],[15,15,220,70,'McParticle','Truth + ancestry',0],[15,140,220,70,'DStep','Geant4 step information',0],[15,265,220,70,'SimulatedHit','Sensitive-detector deposits',2],[650,60,220,85,'CalorimeterHit','Detector response',3],[650,230,220,85,'ReconstructedParticle','Inferred particle objects',4]],edges:['M235 50 H270 V145 H315','M235 175 H315','M235 300 H270 V180 H315','M565 145 H610 V103 H650','M565 180 H610 V273 H650']}}
const graph=computed(()=>definitions[props.kind]||definitions.workflow)
</script>
<template><svg :class="kind" :viewBox="graph.box || (['digit','tracking'].includes(kind)?'0 70 880 180':'0 0 880 350')" class="flow-diagram" :aria-label="kind+' flow diagram'" role="img"><g v-for="(path,i) in graph.edges" :key="path"><path :d="path" fill="none" stroke="#6f859b" stroke-width="1.3"/><path :d="path" :stroke="colors[i%5]" fill="none" pathLength="100" stroke-dasharray="9 91" :stroke-dashoffset="-100*(ambient.cycle+i*.17)" stroke-width="3"/></g><g v-for="(n,i) in graph.nodes" :key="i"><rect :x="n[0]" :y="n[1]" :width="n[2]" :height="n[3]" rx="8" fill="#23262b" stroke="#718094" stroke-opacity=".5"/><rect :x="n[0]+1" :y="n[1]+1" :width="n[2]-2" height="38" rx="8" :fill="colors[n[6]]" fill-opacity=".08"/><path :d="`M${n[0]+16} ${n[1]} H${n[0]+n[2]-16}`" :stroke="colors[n[6]]" stroke-width="2"/><foreignObject :x="n[0]+9" :y="n[1]+15" :width="n[2]-18" :height="n[3]-17"><div xmlns="http://www.w3.org/1999/xhtml" class="node-text"><strong :style="{color:colors[n[6]]}">{{n[4]}}</strong><span>{{n[5]}}</span></div></foreignObject></g></svg></template>
<style scoped>.flow-diagram{display:block;width:100%;height:310px;overflow:visible}.node-text{text-align:center;font-family:'DM Sans',sans-serif;line-height:1.3}.node-text strong{display:block;font-size:18px;font-weight:650}.node-text span{display:block;font-size:13px;color:#bcc2cb;margin-top:8px}.flow-diagram.tracking .node-text strong{font-size:16px}.flow-diagram.tracking .node-text span{font-size:12px;margin-top:6px}.flow-diagram.workflowCompact{height:320px}.workflowCompact .node-text strong{font-size:16px}.workflowCompact .node-text span{font-size:12px;margin-top:8px}.flow-diagram.actsCompact{height:320px}.actsCompact .node-text strong{font-size:16px}.actsCompact .node-text span{font-size:12px;margin-top:9px}.filterCompact .node-text strong{font-size:16px}.filterCompact .node-text span{font-size:12px;margin-top:5px}.filterCompact foreignObject{transform:translateY(-5px)}.digitCompact .node-text strong{font-size:16px}.digitCompact .node-text span{font-size:12px}</style>
